{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would require each local board of education to provide free breakfast and lunch to students in its schools who qualify for free or reduced-price meals under the applicable rules.",
      "rationale": "Conveys the board's obligation to provide both meals free to eligible students in its schools under the applicable rules, adequately paraphrasing the program requirement."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Subject to available funding, the state would reimburse each local education agency for the cost of meals served to students eligible for reduced-price meals, after all available federal funds have been applied.",
      "rationale": "Captures the reimbursement obligation, funding condition, reduced-price eligibility, and requirement to apply all available federal funds first; the preceding sentence identifies the meals as breakfast and lunch."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "The bill would also remove the phrase “regardless of its participation” and delete subdivision (10) from Tennessee Code Annotated, § 49-6-2303.",
      "rationale": "Identifies the phrase and section but omits subdivision (5), the specific target of the phrase deletion."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would also remove the phrase “regardless of its participation” and delete subdivision (10) from Tennessee Code Annotated, § 49-6-2303.",
      "rationale": "Explicitly identifies the deletion of § 49-6-2303(10)."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "In § 49-2-114(a), it would replace a reference to students who “receive free or reduced-price school lunches” with a reference to students whose household income meets the federal eligibility requirements for those lunches.",
      "rationale": "Identifies the amended provision and the change from receiving lunches to household-income eligibility under federal requirements."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025, and apply beginning with the 2025–2026 school year.",
      "rationale": "States the effective date and conveys ongoing application beginning with the specified school year."
    }
  ]
}
